"""Async engine factory, session dependency and declarative base.

Platform conventions baked in here:
  * primary keys are UUID v4 generated by the database (gen_random_uuid())
  * every business row is scoped by org_id (and optionally site_id)
  * deletes are soft (deleted_at IS NOT NULL) unless a task explicitly asks for hard delete
  * money is stored as integer cents, never float
"""
from __future__ import annotations

import os
from collections.abc import AsyncIterator

from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker, create_async_engine
from sqlalchemy.orm import DeclarativeBase

DEFAULT_URL = "postgresql+psycopg://postgres@127.0.0.1:55432/alpha"


class Base(DeclarativeBase):
    pass


def database_url() -> str:
    return os.environ.get("DATABASE_URL", DEFAULT_URL)


def make_engine(url: str | None = None):
    return create_async_engine(url or database_url(), pool_pre_ping=True, future=True)


def make_sessionmaker(engine) -> async_sessionmaker[AsyncSession]:
    return async_sessionmaker(engine, expire_on_commit=False, class_=AsyncSession)


async def get_session(request) -> AsyncIterator[AsyncSession]:
    """FastAPI dependency. Takes `request` so it is not treated as a query parameter."""
    factory = request.app.state.sessionmaker
    async with factory() as session:
        yield session


async def healthcheck(engine) -> str:
    async with engine.connect() as conn:
        return (await conn.execute(text("select version()"))).scalar_one()
